"use strict";

// The same defect with the computed key on a METHOD rather than a plain
// property -- the form where BOTH the value (a method's implicit
// "value", its BODY) and the invocation are deferred, and only the key
// runs at object-construction time. An analyzer that treats a
// `MethodDeclaration` as function-like and stops there unconditionally
// never sees this key at all unless it asks about the key BEFORE that
// stop -- and, distinctly from RWF-019's class case, unless it also asks
// about a `MethodDeclaration` whose PARENT is an object literal, not a
// class.
function dangerousOp(input) {
  return require("./danger").explode(input);
}

function safeOp(input) {
  return "safe:" + input;
}

function bail() {
  throw new Error("fast mode is not supported here");
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  const mode = {
    // The BODY never runs -- nothing calls this method. The KEY runs
    // while the object literal is being built, and throws.
    [bail()]() {
      return "unreachable body";
    },
  };
  void mode;
}

module.exports = safeOp;
